import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.Bg-Zxr5O.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Data-Input-and-Output.md","filePath":"manual-zh/Data-Input-and-Output.md","lastUpdated":1785684581000}'),n={name:"manual-zh/Data-Input-and-Output.md"};function o(_,t,E,T,p,u){return r(),a("div",null,[...t[0]||(t[0]=[e('<h2 id="_8-数据输入与输出" tabindex="-1">8 数据输入与输出 <a class="header-anchor" href="#_8-数据输入与输出" aria-label="Permalink to &quot;8 数据输入与输出&quot;">​</a></h2><p>数据是 PSPP 语言的核心。每个数据都属于一个_个案_（也称为_观测_）。每个个案代表一个个体或“实验单元”。例如，在一项调查结果中，受访者的姓名、性别、年龄等以及他们的回答都是数据，与单个受访者相关的数据就是一个个案。本章考察 PSPP 用于定义变量以及读写数据的命令。还有替代命令可用于从预定义来源（如系统文件或数据库）读取数据（参见 <a href="./GET">GET DATA</a>）。</p><blockquote><p><strong>注意：</strong> 这些命令告诉 PSPP 如何读取数据，但数据在实际执行某个规程之前不会被真正读取。</p></blockquote><table tabindex="0"><thead><tr><th>• BEGIN DATA</th><th></th><th>在语法文件中嵌入数据。</th></tr></thead><tbody><tr><td>• CLOSE FILE HANDLE</td><td></td><td>关闭文件句柄。</td></tr><tr><td>• DATAFILE ATTRIBUTE</td><td></td><td>在数据文件上设置自定义属性。</td></tr><tr><td>• DATASET</td><td></td><td>管理多个数据集。</td></tr><tr><td>• DATA LIST</td><td></td><td>基础的数据读取命令。</td></tr><tr><td>• END CASE</td><td></td><td>输出当前个案。</td></tr><tr><td>• END FILE</td><td></td><td>终止当前的输入程序。</td></tr><tr><td>• FILE HANDLE</td><td></td><td>支持特殊文件格式。</td></tr><tr><td>• INPUT PROGRAM</td><td></td><td>支持复杂的输入程序。</td></tr><tr><td>• LIST</td><td></td><td>列出活动数据集中的个案。</td></tr><tr><td>• NEW FILE</td><td></td><td>清空活动数据集。</td></tr><tr><td>• PRINT</td><td></td><td>以打印格式显示值。</td></tr><tr><td>• PRINT EJECT</td><td></td><td>弹出当前页然后打印。</td></tr><tr><td>• PRINT SPACE</td><td></td><td>打印空行。</td></tr><tr><td>• REREAD</td><td></td><td>再次查看前一行输入。</td></tr><tr><td>• WRITE</td><td></td><td>以写入格式显示值。</td></tr></tbody></table>',4)])])}const A=d(n,[["render",o]]);export{l as __pageData,A as default};
